-- PostgreSQL: range-partition events by month, then prune by filtering on the key
CREATE TABLE events (
  event_id   bigint GENERATED ALWAYS AS IDENTITY,
  user_id    bigint      NOT NULL,
  event_ts   timestamptz NOT NULL,
  payload    jsonb,
  PRIMARY KEY (event_id, event_ts)           -- partition key must be in the PK
) PARTITION BY RANGE (event_ts);

CREATE TABLE events_2026_10 PARTITION OF events
  FOR VALUES FROM ('2026-10-01') TO ('2026-11-01');

-- Prunes to one partition because the filter is on the bare partition column
EXPLAIN SELECT count(*) FROM events
WHERE event_ts >= '2026-10-10' AND event_ts < '2026-10-11';

# Airflow TaskFlow API: a daily, idempotent chunk-and-embed pipeline
from datetime import datetime, timedelta
from airflow.decorators import dag, task

@dag(
    schedule="@daily",
    start_date=datetime(2026, 9, 1),
    catchup=False,                      # backfill explicitly, not on deploy
    default_args={"retries": 3, "retry_delay": timedelta(minutes=5)},
    max_active_runs=1,
    tags=["rag"],
)
def docs_to_vectors():
    @task
    def list_changed(data_interval_start=None, data_interval_end=None) -> list[str]:
        # Only documents updated inside this run's window -> safe to re-run
        return fetch_changed_doc_ids(data_interval_start, data_interval_end)

    @task
    def embed_batch(doc_ids: list[str]) -> int:
        # Upsert by deterministic chunk id, so retries never duplicate
        return upsert_chunks(doc_ids)

    embed_batch(list_changed())

docs_to_vectors()

