CREATE EXTENSION IF NOT EXISTS vector;

CREATE TABLE chunks (
  chunk_id   text PRIMARY KEY,
  doc_id     text        NOT NULL,
  tenant_id  text        NOT NULL,
  body       text        NOT NULL,
  embedding  vector(1024) NOT NULL,
  model      text        NOT NULL,
  updated_at timestamptz NOT NULL DEFAULT now()
);

-- HNSW with cosine distance (operator class must match the query operator)
CREATE INDEX chunks_hnsw ON chunks
  USING hnsw (embedding vector_cosine_ops) WITH (m = 16, ef_construction = 128);

CREATE INDEX chunks_tenant ON chunks (tenant_id);

-- Query time: raise ef_search for recall; iterative scan helps when filters are selective
SET hnsw.ef_search = 100;
SELECT chunk_id, body, embedding <=> $1 AS distance
FROM chunks
WHERE tenant_id = $2
ORDER BY embedding <=> $1
LIMIT 8;
